// Print, for each file given, a JSON line of per-UTF-16-unit categories.
const fs = require("fs");
const path = require("path");
const base = "/home/dhilipsiva/projects/dhilipsiva/botwork/editors/vscode";
const oniguruma = require(path.join(base, "node_modules/vscode-oniguruma"));
const textmate = require(path.join(base, "node_modules/vscode-textmate"));
const grammars = { "source.botwork": "botwork.tmLanguage.json", "source.botwork.suite": "botwork-suite.tmLanguage.json" };
const categories = [["comment.", "comment"], ["string.", "string"], ["constant.character.escape.", "string"], ["constant.numeric.", "number"], ["keyword.control.", "keyword"], ["keyword.other.suite.", "keyword"]];
(async () => {
  const wasm = fs.readFileSync(path.join(base, "node_modules/vscode-oniguruma/release/onig.wasm"));
  await oniguruma.loadWASM(wasm.buffer.slice(wasm.byteOffset, wasm.byteOffset + wasm.byteLength));
  const registry = new textmate.Registry({
    onigLib: Promise.resolve({ createOnigScanner: (p) => new oniguruma.OnigScanner(p), createOnigString: (s) => new oniguruma.OnigString(s) }),
    loadGrammar: async (scope) => grammars[scope] ? textmate.parseRawGrammar(fs.readFileSync(path.join(base, "syntaxes", grammars[scope]), "utf8"), grammars[scope]) : null,
  });
  for (const file of process.argv.slice(2)) {
    const scope = /\.(suite|dataset)\.botwork$/.test(file) ? "source.botwork.suite" : "source.botwork";
    const grammar = await registry.loadGrammar(scope);
    let state = textmate.INITIAL;
    const lines = [];
    for (const line of fs.readFileSync(file, "utf8").split("\n")) {
      const result = grammar.tokenizeLine(line, state);
      state = result.ruleStack;
      const out = new Array(line.length).fill("other");
      for (const token of result.tokens) {
        const named = token.scopes.filter((s) => !s.startsWith("punctuation.definition."));
        const inner = named[named.length - 1];
        const hit = categories.find(([prefix]) => inner.startsWith(prefix));
        // Inside a comment or string anywhere in the stack counts as that.
        const outer = token.scopes.find((s) => s.startsWith("comment.") || s.startsWith("string."));
        const category = hit ? hit[1] : outer ? (outer.startsWith("comment.") ? "comment" : "string") : "other";
        for (let i = token.startIndex; i < Math.min(token.endIndex, line.length); i++) out[i] = category;
      }
      lines.push(out);
    }
    console.log(JSON.stringify({ file, lines }));
  }
})();
